-- Lost update: Two withdrawals read the balance, subtract in the application, and write it back.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 30, computed in the app
COMMIT;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 20, computed in the app
COMMIT;

-- Dirty read: T1 debits A, then rolls back. T2 copies A into a report row B in between.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 60, computed in the app
ROLLBACK;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :v WHERE id = 'B';  -- B = A, computed in the app
COMMIT;

-- Non-repeatable read: T1 reads A twice. T2 changes A and commits in between.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
SELECT v FROM accounts WHERE id = 'A';
COMMIT;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 30, computed in the app
COMMIT;

-- Read skew: An auditor (T1) sums two accounts while a transfer (T2) moves 20 from A to B.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
SELECT v FROM accounts WHERE id = 'B';
COMMIT;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
SELECT v FROM accounts WHERE id = 'B';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 20, computed in the app
UPDATE accounts SET v = :new_b WHERE id = 'B';  -- B = B + 20, computed in the app
COMMIT;

-- Phantom read: T1 totals the orders twice. T2 inserts a new order in between.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT SUM(v) FROM orders WHERE tag = 'order';
SELECT SUM(v) FROM orders WHERE tag = 'order';
COMMIT;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
INSERT INTO orders (id, tag, v) VALUES ('o3', 'order', 30);
COMMIT;

-- Lost update fixed with FOR UPDATE: The same withdrawals, but each reads with SELECT … FOR UPDATE.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A' FOR UPDATE;
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 30, computed in the app
COMMIT;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A' FOR UPDATE;
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 20, computed in the app
COMMIT;

-- Lost update fixed with an atomic UPDATE: The same withdrawals as one statement each: UPDATE accounts SET v = v - 30.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
UPDATE accounts SET v = v - 30 WHERE id = 'A';
COMMIT;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
UPDATE accounts SET v = v - 20 WHERE id = 'A';
COMMIT;

-- Opposite-order transfers: T1 moves 10 from A to B while T2 moves 10 from B to A: they touch the same rows in opposite order.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A - 10, computed in the app
SELECT v FROM accounts WHERE id = 'B';
UPDATE accounts SET v = :new_b WHERE id = 'B';  -- B = B + 10, computed in the app
COMMIT;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM accounts WHERE id = 'B';
UPDATE accounts SET v = :new_b WHERE id = 'B';  -- B = B - 10, computed in the app
SELECT v FROM accounts WHERE id = 'A';
UPDATE accounts SET v = :new_a WHERE id = 'A';  -- A = A + 10, computed in the app
COMMIT;

-- Hot counter: Three sessions increment one hot row at the same moment.
-- Each session runs in its own connection; the lab interleaves their statements.

-- ── Session T1 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM counters WHERE id = 'hits';
UPDATE counters SET v = :new_hits WHERE id = 'hits';  -- hits = hits + 10, computed in the app
COMMIT;

-- ── Session T2 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM counters WHERE id = 'hits';
UPDATE counters SET v = :new_hits WHERE id = 'hits';  -- hits = hits + 10, computed in the app
COMMIT;

-- ── Session T3 ──────────────────────────────
BEGIN;  -- isolation level chosen in the lab
SELECT v FROM counters WHERE id = 'hits';
UPDATE counters SET v = :new_hits WHERE id = 'hits';  -- hits = hits + 10, computed in the app
COMMIT;
